-- >>> supabase/schemas/05_geo/040_place_search.sql
-- Geo · place search
--
-- One search over the places a ride can start, end or meet at that are picked by name:
-- cities and road junctions (D71). Streets are not searched here; they are picked inside a
-- chosen city, straight from public.streets. A function rather than two table reads because
-- the picker needs one ranked list across both catalogs with plain latitude / longitude,
-- which a table read of a geography column does not give.

-- Returns at most p_limit places whose Hebrew or English name contains p_query, names that
-- start with it first. Runs with the caller's rights: the tables' own policies apply.
-- junction_kind tells a junction from an interchange so the client can word the label.
create function public.search_places(
  p_query text,
  p_kinds text[] default array['city', 'junction'],
  p_limit integer default 20
)
returns table (
  place_kind    text,
  place_id      text,
  name_he       text,
  name_en       text,
  junction_kind text,
  roads         text,
  city_id       text,
  lat           double precision,
  lng           double precision
)
language plpgsql
stable
set search_path = ''
as $$
declare
  v_query   text := btrim(coalesce(p_query, ''));
  v_pattern text;
begin
  if char_length(v_query) not between 1 and 80 then
    raise exception 'place_query_invalid' using errcode = '22023';
  end if;
  if p_kinds is null or cardinality(p_kinds) = 0 or not (p_kinds <@ array['city', 'junction']) then
    raise exception 'place_kinds_invalid' using errcode = '22023';
  end if;
  if p_limit is null or p_limit not between 1 and 50 then
    raise exception 'place_limit_invalid' using errcode = '22023';
  end if;

  -- The query is matched literally: pattern characters typed by the member are escaped.
  v_pattern := '%' || replace(replace(replace(v_query, '\', '\\'), '%', '\%'), '_', '\_') || '%';

  return query
  select p.place_kind, p.place_id, p.name_he, p.name_en, p.junction_kind, p.roads, p.city_id,
         extensions.st_y(p.location::extensions.geometry),
         extensions.st_x(p.location::extensions.geometry)
    from (
      -- A city without a centre cannot be placed on a route, so it is not a ride place.
      select 'city'::text as place_kind, c.city_id as place_id, c.name_he, c.name_en,
             null::text as junction_kind, null::text as roads, c.city_id, c.location
        from public.cities c
       where 'city' = any (p_kinds)
         and c.location is not null
         and (c.name_he ilike v_pattern or lower(c.name_en) like lower(v_pattern))
      union all
      select 'junction', j.junction_id::text, j.name_he, j.name_en, j.kind, j.roads, null, j.location
        from public.road_junctions j
       where 'junction' = any (p_kinds)
         and (j.name_he ilike v_pattern or lower(j.name_en) like lower(v_pattern))
    ) p
   -- Total order, so equal names always come back in the same sequence.
   order by (p.name_he ilike substr(v_pattern, 2) or lower(p.name_en) like lower(substr(v_pattern, 2))) desc,
            p.name_he, p.place_kind, p.place_id
   limit p_limit;
end;
$$;
comment on function public.search_places(text, text[], integer) is
  'Place picker search over cities and road junctions (D71): at most 50 rows, names starting with the query first.';

grant execute on function public.search_places(text, text[], integer) to authenticated;

-- >>> supabase/schemas/10_identity/010_users.sql
-- Identity · users (public profile)
--
-- One row per member, holding only what other members may see. Private fields, account state
-- and counters live in their own 1:1 tables (user_private, user_account, user_stats), so a
-- row another member can select never contains anything private.

create table public.users (
  -- Same id as the auth account; removing the auth account removes the member.
  id                 uuid primary key references auth.users (id) on delete cascade,
  -- Public, shareable identifier used in profile links.
  share_handle       text not null unique check (share_handle ~ '^[a-z0-9_]{3,30}$'),
  -- Empty until the member completes the first onboarding step.
  display_name       text check (char_length(display_name) between 1 and 50),
  -- Free text; links are rejected so the profile cannot be used for advertising.
  biography          text check (
                       char_length(biography) <= 200
                       and biography !~* '(https?://|www\.|[\w.-]+\.[a-z]{2,})'),
  avatar_url         text,
  city_id            text references public.cities (city_id),
  -- 'Private' hides the member's posts and follower lists from non-followers.
  privacy_mode       text not null default 'Public' check (privacy_mode in ('Public', 'Private')),
  privacy_changed_at timestamptz,
  -- 0 none · 1 phone · 2 identity document · 3 verified badge.
  verification_level smallint not null default 0 check (verification_level between 0 and 3),
  -- BCP 47 tag of the member's interface language.
  preferred_language text check (char_length(preferred_language) between 2 and 35),
  -- Mirror of user_account.status = 'active', maintained by trigger. Kept on this row so the
  -- visibility policy is a plain column test rather than a join on every profile read.
  is_active          boolean not null default false,
  -- Search document over name and handle; `simple` keeps Hebrew tokens unstemmed.
  search_vector      tsvector generated always as (
                       to_tsvector('simple', coalesce(display_name, '') || ' ' || share_handle)) stored,
  created_at         timestamptz not null default now(),
  updated_at         timestamptz not null default now()
);
comment on table public.users is 'Public profile of a member. Contains nothing private.';

-- Member search: whole-word match, then substring match on the display name.
create index users_search_gin_idx on public.users using gin (search_vector) where is_active;
create index users_display_name_trgm_idx on public.users
  using gin (display_name extensions.gin_trgm_ops) where is_active;
-- City filter in member search and city statistics.
create index users_city_idx on public.users (city_id) where is_active;

create trigger users_set_updated_at
  before update on public.users
  for each row execute function kc_private.set_updated_at();

alter table public.users enable row level security;
alter table public.users force row level security;

-- A member sees active profiles, and always their own (whatever its account state).
create policy users_select_active_or_self on public.users
  for select to authenticated
  using (is_active or id = (select auth.uid()));

-- A member edits their own profile; which columns is decided by the grant below.
create policy users_update_self on public.users
  for update to authenticated
  using (id = (select auth.uid()))
  with check (id = (select auth.uid()));

grant select on public.users to authenticated;
-- Handle, privacy mode, verification level and is_active change only through server code.
grant update (display_name, biography, avatar_url, city_id, preferred_language)
  on public.users to authenticated;

-- >>> supabase/schemas/10_identity/020_user_private.sql
-- Identity · user_private (owner-only data)
--
-- Personal details and preferences that only the member may read. Kept out of `users` so
-- that no policy mistake on the public profile can ever expose them.

create table public.user_private (
  user_id                     uuid primary key references public.users (id) on delete cascade,
  -- Contact number shown to a counterparty only through a dedicated RPC.
  contact_phone               text check (char_length(btrim(contact_phone)) between 1 and 20),
  -- Used for the 18+ rule and age-restricted worlds; written only through set_date_of_birth.
  date_of_birth               date,
  -- Default pickup address, prefilled into new posts. Both parts or neither.
  profile_street              text check (char_length(profile_street) between 1 and 80),
  -- Digits with an optional entrance letter, Latin or Hebrew (U+05D0–U+05EA, written as
  -- escapes because Hebrew text is allowed only in locale files).
  profile_street_number       text check (profile_street_number ~ '^[0-9]+[A-Za-z\u05D0-\u05EA]?$'),
  -- Per-category push settings and quiet hours.
  notification_preferences    jsonb not null default '{}'::jsonb
                                check (jsonb_typeof(notification_preferences) = 'object'),
  -- Whether other members see the "active recently" indicator.
  show_active_status          boolean not null default true,
  -- One-time explainer and nudge dismissals.
  closure_explainer_dismissed boolean not null default false,
  first_post_nudge_dismissed  boolean not null default false,
  -- The member chose to fill in basic details later.
  basic_info_skipped          boolean not null default false,
  updated_at                  timestamptz not null default now(),
  constraint user_private_address_pair_chk
    check ((profile_street is null) = (profile_street_number is null))
);
comment on table public.user_private is 'Personal details and preferences readable only by their owner.';

create trigger user_private_set_updated_at
  before update on public.user_private
  for each row execute function kc_private.set_updated_at();

alter table public.user_private enable row level security;
alter table public.user_private force row level security;

create policy user_private_select_self on public.user_private
  for select to authenticated
  using (user_id = (select auth.uid()));

create policy user_private_update_self on public.user_private
  for update to authenticated
  using (user_id = (select auth.uid()))
  with check (user_id = (select auth.uid()));

grant select on public.user_private to authenticated;
-- date_of_birth is excluded: it is written only by set_date_of_birth, which enforces 18+.
grant update (
  contact_phone, profile_street, profile_street_number, notification_preferences,
  show_active_status, closure_explainer_dismissed, first_post_nudge_dismissed, basic_info_skipped
) on public.user_private to authenticated;

-- >>> supabase/schemas/10_identity/030_user_account.sql
-- Identity · user_account (server-written account state)
--
-- Account status, onboarding progress, sanctions and the 30-day deletion grace period.
-- The member may read their own row; nothing here is writable from a device.

insert into kc_private.fsm_state (machine_id, status) values
  ('account_status', 'pending_verification'),
  ('account_status', 'active'),
  ('account_status', 'suspended_for_false_reports'),
  ('account_status', 'suspended_admin'),
  ('account_status', 'banned'),
  ('account_status', 'pending_deletion'),
  ('onboarding', 'pending_basic_info'),
  ('onboarding', 'pending_avatar'),
  ('onboarding', 'completed');

insert into kc_private.fsm_edge (machine_id, from_status, to_status) values
  ('account_status', 'pending_verification', 'active'),
  ('account_status', 'pending_verification', 'suspended_for_false_reports'),
  ('account_status', 'pending_verification', 'suspended_admin'),
  ('account_status', 'pending_verification', 'banned'),
  ('account_status', 'pending_verification', 'pending_deletion'),
  ('account_status', 'active', 'suspended_for_false_reports'),
  ('account_status', 'active', 'suspended_admin'),
  ('account_status', 'active', 'banned'),
  ('account_status', 'active', 'pending_deletion'),
  ('account_status', 'suspended_for_false_reports', 'active'),
  ('account_status', 'suspended_for_false_reports', 'suspended_admin'),
  ('account_status', 'suspended_for_false_reports', 'banned'),
  ('account_status', 'suspended_admin', 'active'),
  ('account_status', 'suspended_admin', 'banned'),
  ('account_status', 'banned', 'active'),
  -- Restoring within the grace period returns to the status held before the request.
  ('account_status', 'pending_deletion', 'active'),
  ('account_status', 'pending_deletion', 'pending_verification'),
  ('onboarding', 'pending_basic_info', 'pending_avatar'),
  -- Deferred basic details (FR-AUTH-015): the member skipped the avatar step.
  ('onboarding', 'pending_basic_info', 'completed'),
  ('onboarding', 'pending_avatar', 'completed');

create table public.user_account (
  user_id                     uuid primary key references public.users (id) on delete cascade,
  status                      text not null default 'pending_verification',
  -- End of a temporary suspension; null for every other status.
  status_until                timestamptz,
  onboarding_state            text not null default 'pending_basic_info',
  -- Moderation counters behind the false-report sanction ladder.
  false_reports_count         integer not null default 0 check (false_reports_count >= 0),
  false_report_sanction_count smallint not null default 0 check (false_report_sanction_count between 0 and 3),
  -- A member barred from the food world cannot post there until this time.
  food_posting_banned_until   timestamptz,
  verified_at                 timestamptz,
  verification_method         text check (verification_method in ('manual', 'document', 'provider', 'org_vouch')),
  -- Account deletion: requested → hidden at once → purged after the grace period.
  deletion_requested_at       timestamptz,
  deletion_purge_at           timestamptz,
  status_before_deletion      text check (status_before_deletion in ('active', 'pending_verification')),
  updated_at                  timestamptz not null default now(),
  -- A purge date exists exactly while the account is pending deletion.
  constraint user_account_pending_deletion_chk
    check ((status = 'pending_deletion') = (deletion_purge_at is not null)),
  constraint user_account_deletion_fields_chk
    check ((deletion_purge_at is null) = (deletion_requested_at is null)
       and (deletion_purge_at is null) = (status_before_deletion is null))
);
comment on table public.user_account is 'Account status, onboarding and deletion state. Written only by server code.';

-- Daily purge job: accounts whose grace period has ended.
create index user_account_purge_due_idx on public.user_account (deletion_purge_at)
  where deletion_purge_at is not null;
-- Daily job that lifts expired suspensions.
create index user_account_status_until_idx on public.user_account (status_until)
  where status_until is not null;

create trigger user_account_status_fsm
  before insert or update of status on public.user_account
  for each row execute function kc_private.fsm_guard_status('account_status', 'status');

create trigger user_account_onboarding_fsm
  before insert or update of onboarding_state on public.user_account
  for each row execute function kc_private.fsm_guard_status('onboarding', 'onboarding_state');

create trigger user_account_set_updated_at
  before update on public.user_account
  for each row execute function kc_private.set_updated_at();

-- Keeps users.is_active equal to (status = 'active'), so profile visibility follows the
-- account state in the same transaction that changes it.
create function kc_private.user_account_sync_is_active()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  update public.users u
     set is_active = (new.status = 'active')
   where u.id = new.user_id
     and u.is_active is distinct from (new.status = 'active');
  return null;
end;
$$;

create trigger user_account_sync_is_active
  after insert or update of status on public.user_account
  for each row execute function kc_private.user_account_sync_is_active();

alter table public.user_account enable row level security;
alter table public.user_account force row level security;

create policy user_account_select_self on public.user_account
  for select to authenticated
  using (user_id = (select auth.uid()));

grant select on public.user_account to authenticated;

-- >>> supabase/schemas/10_identity/040_user_stats.sql
-- Identity · user_stats (denormalized counters)
--
-- Counters shown on a profile. They live apart from `users` so that a follow, a reaction or a
-- new post never rewrites the profile row. Maintained by triggers in the modules that own the
-- counted rows; a nightly job recomputes them and records any drift.

create table public.user_stats (
  user_id                    uuid primary key references public.users (id) on delete cascade,
  followers_count            integer not null default 0 check (followers_count >= 0),
  following_count            integer not null default 0 check (following_count >= 0),
  items_given_count          integer not null default 0 check (items_given_count >= 0),
  items_received_count       integer not null default 0 check (items_received_count >= 0),
  -- Open posts by visibility: a viewer is shown the sum they are allowed to see.
  open_posts_public          integer not null default 0 check (open_posts_public >= 0),
  open_posts_followers_only  integer not null default 0 check (open_posts_followers_only >= 0),
  open_posts_only_me         integer not null default 0 check (open_posts_only_me >= 0),
  posts_created_total        integer not null default 0 check (posts_created_total >= 0),
  karma_points               integer not null default 0 check (karma_points >= 0),
  volunteer_hours_total      numeric(10, 2) not null default 0 check (volunteer_hours_total >= 0),
  updated_at                 timestamptz not null default now()
);
comment on table public.user_stats is 'Profile counters, maintained by triggers and reconciled nightly.';

create trigger user_stats_set_updated_at
  before update on public.user_stats
  for each row execute function kc_private.set_updated_at();

alter table public.user_stats enable row level security;
alter table public.user_stats force row level security;

-- Counters are visible exactly when the profile is: the subquery runs under the caller's
-- own access to `users`, so it inherits that table's policy.
create policy user_stats_select_visible_profile on public.user_stats
  for select to authenticated
  using (exists (select 1 from public.users u where u.id = user_stats.user_id));

-- Column grant: the private "only me" count is left out; its owner reads it through an RPC.
grant select (
  user_id, followers_count, following_count, items_given_count, items_received_count,
  open_posts_public, open_posts_followers_only, posts_created_total, karma_points,
  volunteer_hours_total, updated_at
) on public.user_stats to authenticated;

-- >>> supabase/schemas/10_identity/050_auth_user_triggers.sql
-- Identity · auth account → member rows
--
-- The auth service owns sign-up. These triggers on `auth.users` create the member's four rows
-- in the same transaction as the auth account, and activate the member once a contact
-- channel is confirmed. They are SECURITY DEFINER because the auth service's role has no
-- access to the product tables.

-- True when the auth account has proven a contact channel: Google and Apple accounts are
-- verified by the provider; email and phone accounts once their confirmation arrived.
create function kc_private.auth_user_is_verified(p_auth_user auth.users)
returns boolean
language sql
immutable
set search_path = ''
as $$
  select coalesce(p_auth_user.raw_app_meta_data ->> 'provider', 'email') in ('google', 'apple')
      or p_auth_user.email_confirmed_at is not null
      or p_auth_user.phone_confirmed_at is not null;
$$;

-- Returns a share handle no member holds yet: `u_` plus 12 random hex characters. The
-- handle is random rather than derived from the account id, because a prefix of the id is
-- not unique at scale and a collision would fail the sign-up.
create function kc_private.generate_share_handle()
returns text
language plpgsql
volatile
set search_path = ''
as $$
declare
  v_handle text;
begin
  loop
    v_handle := 'u_' || substr(replace(gen_random_uuid()::text, '-', ''), 1, 12);
    exit when not exists (select 1 from public.users u where u.share_handle = v_handle);
  end loop;
  return v_handle;
end;
$$;

-- Creates the profile, private, account and counter rows of a new member.
create function kc_private.handle_new_auth_user()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_meta constant jsonb := coalesce(new.raw_user_meta_data, '{}'::jsonb);
  -- Name offered by the identity provider, else the local part of the email address.
  v_display_name constant text := left(
    coalesce(
      nullif(btrim(coalesce(v_meta ->> 'full_name', v_meta ->> 'name')), ''),
      nullif(split_part(coalesce(new.email, ''), '@', 1), '')),
    50);
begin
  insert into public.users (id, share_handle, display_name, avatar_url)
  values (
    new.id,
    kc_private.generate_share_handle(),
    v_display_name,
    nullif(coalesce(v_meta ->> 'avatar_url', v_meta ->> 'picture'), ''));

  insert into public.user_private (user_id) values (new.id);
  insert into public.user_stats (user_id) values (new.id);
  insert into public.user_account (user_id, status)
  values (
    new.id,
    case when kc_private.auth_user_is_verified(new) then 'active' else 'pending_verification' end);

  return new;
end;
$$;
comment on function kc_private.handle_new_auth_user() is
  'AFTER INSERT on auth.users: creates the member rows; verified accounts start active.';

create trigger on_auth_user_created
  after insert on auth.users
  for each row execute function kc_private.handle_new_auth_user();

-- Activates a member waiting for verification when their email or phone is confirmed.
-- Any other status is left alone: a suspension or a deletion request outranks verification.
create function kc_private.handle_auth_user_verified()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if kc_private.auth_user_is_verified(new) then
    update public.user_account a
       set status = 'active'
     where a.user_id = new.id
       and a.status = 'pending_verification';
  end if;
  return new;
end;
$$;
comment on function kc_private.handle_auth_user_verified() is
  'AFTER UPDATE on auth.users: pending_verification → active once a contact channel is confirmed.';

create trigger on_auth_user_verified
  after update of email_confirmed_at, phone_confirmed_at on auth.users
  for each row execute function kc_private.handle_auth_user_verified();

-- >>> supabase/schemas/10_identity/060_user_devices.sql
-- Identity · user_devices (push tokens, FR-NOTIF-015)
--
-- One row per device a member receives push notifications on. The member registers the
-- token at sign-in, refreshes `last_seen_at` on every app start and deletes the row at
-- sign-out; server code deletes it when the push provider reports the token as dead, when
-- the account is deactivated (FR-SETTINGS-012 AC2) and after 90 days without use.

create table public.user_devices (
  id           uuid primary key default gen_random_uuid(),
  user_id      uuid not null references public.users (id) on delete cascade,
  platform     text not null check (platform in ('ios', 'android', 'web')),
  -- Provider token. Unique: one physical device delivers to one member at a time.
  push_token   text not null unique check (char_length(push_token) between 1 and 4096),
  -- Last app start on this device; drives the 90-day prune (FR-NOTIF-015 AC4).
  last_seen_at timestamptz not null default now(),
  created_at   timestamptz not null default now()
);
comment on table public.user_devices is 'Push tokens of a member''s devices. Owner-only.';

-- Notification dispatch: every token of the recipient.
create index user_devices_user_idx on public.user_devices (user_id);
-- Daily prune job: tokens not seen for 90 days.
create index user_devices_last_seen_idx on public.user_devices (last_seen_at);

alter table public.user_devices enable row level security;
alter table public.user_devices force row level security;

create policy user_devices_select_self on public.user_devices
  for select to authenticated
  using (user_id = (select auth.uid()));

create policy user_devices_insert_self on public.user_devices
  for insert to authenticated
  with check (user_id = (select auth.uid()));

-- Refreshing a registration (upsert on the token) may only touch the caller's own row.
create policy user_devices_update_self on public.user_devices
  for update to authenticated
  using (user_id = (select auth.uid()))
  with check (user_id = (select auth.uid()));

create policy user_devices_delete_self on public.user_devices
  for delete to authenticated
  using (user_id = (select auth.uid()));

grant select, insert, delete on public.user_devices to authenticated;
-- The columns an upsert on `push_token` rewrites; `id` and `created_at` never change.
grant update (user_id, platform, push_token, last_seen_at) on public.user_devices to authenticated;

-- >>> supabase/schemas/10_identity/070_legal_documents.sql
-- Identity · legal documents (FR-SETTINGS-010)
--
-- Terms of service and privacy policy are published from the server. `legal_documents` is
-- the current pointer of each document; `legal_document_versions` is the immutable history
-- a member's consent refers to. Both are written only by the admin publishing RPC.

create table public.legal_documents (
  id                     uuid primary key default gen_random_uuid(),
  doc_type               text not null unique check (doc_type in ('terms', 'privacy')),
  -- 0 until the first version is published.
  current_version        integer not null default 0 check (current_version >= 0),
  current_effective_date timestamptz not null,
  -- Newest version a member must have accepted: minor edits do not raise it.
  last_material_version  integer not null default 0,
  last_material_severity text check (last_material_severity in ('standard', 'critical')),
  updated_at             timestamptz not null default now(),
  constraint legal_documents_material_version_chk
    check (last_material_version between 0 and current_version)
);
comment on table public.legal_documents is 'Current version pointer of each legal document.';

create trigger legal_documents_set_updated_at
  before update on public.legal_documents
  for each row execute function kc_private.set_updated_at();

create table public.legal_document_versions (
  id             uuid primary key default gen_random_uuid(),
  doc_type       text not null references public.legal_documents (doc_type),
  version        integer not null check (version >= 1),
  -- BCP 47 tag of the text.
  language       text not null default 'he' check (char_length(language) between 2 and 35),
  -- A version published ahead of time is shown, but asks for consent only from this date.
  effective_date timestamptz not null,
  body_md        text not null check (char_length(body_md) > 0),
  -- SHA-256 of body_md, set by trigger: proves which text a consent referred to.
  content_hash   text not null,
  -- minor: no consent needed · standard: 7 days of notice · critical: blocks at once.
  severity       text not null check (severity in ('minor', 'standard', 'critical')),
  change_summary text,
  -- The publishing admin; null once that account has been removed.
  published_by   uuid references public.users (id) on delete set null,
  published_at   timestamptz not null default now(),
  -- Also serves the foreign key on doc_type and "newest version of a document".
  constraint legal_document_versions_doc_version_key unique (doc_type, version),
  constraint legal_document_versions_summary_chk
    check (severity = 'minor' or char_length(btrim(change_summary)) > 0)
);
comment on table public.legal_document_versions is 'Immutable history of published legal texts.';

-- Foreign key lookup when a publisher's account is removed.
create index legal_document_versions_published_by_idx
  on public.legal_document_versions (published_by) where published_by is not null;

-- Stamps the content hash, so it never depends on what the publisher sent.
create function kc_private.legal_document_versions_set_hash()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  new.content_hash := encode(sha256(convert_to(new.body_md, 'UTF8')), 'hex');
  return new;
end;
$$;

create trigger legal_document_versions_set_hash
  before insert on public.legal_document_versions
  for each row execute function kc_private.legal_document_versions_set_hash();

-- A published version never changes and is never removed. The single exception is the
-- foreign key clearing `published_by` when the publisher's account is removed.
create function kc_private.legal_document_versions_immutable()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if tg_op = 'UPDATE' and new.published_by is null
     and to_jsonb(new) - 'published_by' = to_jsonb(old) - 'published_by' then
    return new;
  end if;
  raise exception 'append_only' using errcode = 'P0001', detail = 'legal_document_versions';
end;
$$;

create trigger legal_document_versions_immutable
  before update or delete on public.legal_document_versions
  for each row execute function kc_private.legal_document_versions_immutable();

alter table public.legal_documents enable row level security;
alter table public.legal_documents force row level security;
alter table public.legal_document_versions enable row level security;
alter table public.legal_document_versions force row level security;

-- Published legal text is public: the sign-up screen shows the terms and the privacy policy
-- before an account exists (FR-AUTH-002 AC3; PM decision 2026-11-10). This is the only
-- product table a signed-out caller can read.
create policy legal_documents_select_anyone on public.legal_documents
  for select to anon, authenticated
  using (true);

create policy legal_document_versions_select_anyone on public.legal_document_versions
  for select to anon, authenticated
  using (true);

grant select on public.legal_documents to anon, authenticated;
grant select on public.legal_document_versions to anon, authenticated;

-- >>> supabase/schemas/10_identity/080_user_consents.sql
-- Identity · user_consents
--
-- One append-only record of everything a member agreed to: the legal documents, the driver
-- declaration of the rides world and the code of conduct of the housing world. A row is the
-- evidence of a consent, so it is never changed and leaves only together with its member.

create table public.user_consents (
  id           uuid primary key default gen_random_uuid(),
  user_id      uuid not null references public.users (id) on delete cascade,
  -- terms / privacy refer to legal_document_versions; the two world consents are versioned
  -- by the module that asks for them.
  consent_kind text not null
                 check (consent_kind in ('terms', 'privacy', 'driver_declaration', 'housing_conduct')),
  version      integer not null check (version >= 1),
  accepted_at  timestamptz not null default now(),
  -- Evidence of the circumstances of the consent; all three may be unknown.
  locale       text check (char_length(locale) between 2 and 35),
  ip_address   inet,
  user_agent   text check (char_length(user_agent) <= 500),
  -- A version is accepted once. Also serves "newest accepted version of a kind" for a
  -- member (session start, world gates) and the foreign key on user_id.
  constraint user_consents_user_kind_version_key unique (user_id, consent_kind, version)
);
comment on table public.user_consents is 'Append-only record of a member''s consents. Written only by server code.';

-- No update at all; a delete only as part of removing the member (the cascade runs after
-- the profile row is gone, a direct delete does not).
create function kc_private.user_consents_append_only()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if tg_op = 'DELETE' and not exists (select 1 from public.users u where u.id = old.user_id) then
    return old;
  end if;
  raise exception 'append_only' using errcode = 'P0001', detail = 'user_consents';
end;
$$;

create trigger user_consents_append_only
  before update or delete on public.user_consents
  for each row execute function kc_private.user_consents_append_only();

alter table public.user_consents enable row level security;
alter table public.user_consents force row level security;

create policy user_consents_select_self on public.user_consents
  for select to authenticated
  using (user_id = (select auth.uid()));

grant select on public.user_consents to authenticated;

-- The signed-in caller, for RPCs that act on the caller's own data.
create function kc_private.require_caller()
returns uuid
language plpgsql
stable
set search_path = ''
as $$
declare
  v_user_id constant uuid := (select auth.uid());
begin
  if v_user_id is null then
    raise exception 'unauthenticated' using errcode = '42501';
  end if;
  return v_user_id;
end;
$$;
comment on function kc_private.require_caller() is 'Returns auth.uid(); raises unauthenticated without a session.';

-- Records one consent with its evidence and returns the stored row. Recording the same
-- version again keeps the first row. The world modules call this from their own RPCs after
-- checking the version they require.
create function kc_private.record_consent(
  p_user_id uuid, p_kind text, p_version integer, p_locale text, p_user_agent text)
returns public.user_consents
language plpgsql
set search_path = ''
as $$
declare
  -- The API gateway forwards the device address as the first hop of this header.
  v_forwarded constant text := btrim(split_part(
    nullif(current_setting('request.headers', true), '')::jsonb ->> 'x-forwarded-for', ',', 1));
  v_ip inet;
  v_row public.user_consents;
begin
  begin
    v_ip := coalesce(nullif(v_forwarded, '')::inet, inet_client_addr());
  exception when invalid_text_representation then
    v_ip := null;
  end;

  insert into public.user_consents (user_id, consent_kind, version, locale, ip_address, user_agent)
  values (p_user_id, p_kind, p_version, nullif(btrim(p_locale), ''), v_ip, left(p_user_agent, 500))
  on conflict (user_id, consent_kind, version) do nothing;

  select c.* into strict v_row
    from public.user_consents c
   where c.user_id = p_user_id and c.consent_kind = p_kind and c.version = p_version;
  return v_row;
end;
$$;

-- The caller accepts a published version of a legal document (FR-AUTH-002 AC5,
-- FR-SETTINGS-010 AC3/AC4). Only a version that satisfies the consent gate is accepted:
-- from the last material version up to the current one.
create function public.accept_legal_document(
  p_doc_type text, p_version integer, p_locale text default null, p_user_agent text default null)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user_id constant uuid := kc_private.require_caller();
  v_document public.legal_documents;
  v_consent public.user_consents;
begin
  select d.* into v_document from public.legal_documents d where d.doc_type = p_doc_type;
  if not found then
    raise exception 'unknown_legal_document' using errcode = 'P0001';
  end if;
  if p_version is null or p_version < greatest(v_document.last_material_version, 1)
     or p_version > v_document.current_version then
    raise exception 'legal_version_out_of_range' using errcode = 'P0001';
  end if;

  v_consent := kc_private.record_consent(v_user_id, p_doc_type, p_version, p_locale, p_user_agent);
  return jsonb_build_object('acceptance_id', v_consent.id, 'accepted_at', v_consent.accepted_at);
end;
$$;
comment on function public.accept_legal_document(text, integer, text, text) is
  'Records the caller''s consent to a published legal document version.';
grant execute on function public.accept_legal_document(text, integer, text, text) to authenticated;

-- >>> supabase/schemas/10_identity/090_account_rpcs.sql
-- Identity · account RPCs (onboarding, date of birth, account deletion)
--
-- `user_account` and `user_private.date_of_birth` are not writable from a device. These are
-- the named moves a member may make on their own account. Errors are raised with SQLSTATE
-- P0001 and a stable snake_case message the app maps to its error types.

-- ── Onboarding (FR-AUTH-010 AC5, FR-AUTH-015) ───────────────────────────────
-- Moves the caller's onboarding forward. Leaving step 1 requires a display name, a city and
-- a date of birth on file, so a modified client cannot skip the step.
create function public.set_onboarding_state(p_state text)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user_id constant uuid := kc_private.require_caller();
  v_current text;
begin
  select a.onboarding_state into v_current
    from public.user_account a where a.user_id = v_user_id for update;
  if not found then
    raise exception 'user_not_found' using errcode = 'P0001';
  end if;

  if v_current = 'pending_basic_info' and p_state is distinct from v_current and not exists (
       select 1
         from public.users u
         join public.user_private p on p.user_id = u.id
        where u.id = v_user_id
          and nullif(btrim(u.display_name), '') is not null
          and u.city_id is not null
          and p.date_of_birth is not null) then
    raise exception 'onboarding_basic_info_missing' using errcode = 'P0001';
  end if;

  begin
    update public.user_account a set onboarding_state = p_state where a.user_id = v_user_id;
  exception when sqlstate 'P0001' then
    -- The machine refused the move (backwards, or not a state): one error for the app.
    raise exception 'onboarding_transition_invalid' using errcode = 'P0001', detail = sqlerrm;
  end;
end;
$$;
comment on function public.set_onboarding_state(text) is
  'Moves the caller''s onboarding along its machine; step 1 needs name, city and date of birth.';
grant execute on function public.set_onboarding_state(text) to authenticated;

-- ── Date of birth (FR-AUTH-010 AC2.d, FR-PROFILE-007 AC7, D109) ─────────────
-- Stores the caller's date of birth. The member must be at least 18 on the day of the call;
-- a later correction is held to the same rule.
create function public.set_date_of_birth(p_date date)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user_id constant uuid := kc_private.require_caller();
begin
  if p_date is null or p_date > current_date or p_date < date '1900-01-01' then
    raise exception 'invalid_date_of_birth' using errcode = 'P0001';
  end if;
  if p_date > (current_date - interval '18 years')::date then
    raise exception 'underage' using errcode = 'P0001';
  end if;

  update public.user_private p set date_of_birth = p_date where p.user_id = v_user_id;
  if not found then
    raise exception 'user_not_found' using errcode = 'P0001';
  end if;
end;
$$;
comment on function public.set_date_of_birth(date) is 'Stores the caller''s date of birth; rejects anyone under 18.';
grant execute on function public.set_date_of_birth(date) to authenticated;

-- ── Account deletion: 30 days of grace (D108, FR-SETTINGS-012, FR-AUTH-016) ─
-- Whatever moves an account out of pending_deletion (a restore, or any later server move),
-- the deletion fields are cleared here, in one place, so no writer can leave them behind.
create function kc_private.user_account_leave_pending_deletion()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  new.deletion_requested_at := null;
  new.deletion_purge_at := null;
  new.status_before_deletion := null;
  return new;
end;
$$;

create trigger user_account_leave_pending_deletion
  before update of status on public.user_account
  for each row
  when (old.status = 'pending_deletion' and new.status <> 'pending_deletion')
  execute function kc_private.user_account_leave_pending_deletion();

-- Deactivates the caller's account and returns the purge date. The profile disappears for
-- everyone else at once (users.is_active), push stops, and nothing else is removed, so a
-- restore is complete. Calling it again returns the same date. A suspended or banned
-- member cannot use it to step out of a sanction.
create function public.request_account_deletion()
returns timestamptz
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user_id constant uuid := kc_private.require_caller();
  v_account public.user_account;
  v_purge_at constant timestamptz := now() + interval '30 days';
begin
  select a.* into v_account from public.user_account a where a.user_id = v_user_id for update;
  if not found then
    raise exception 'user_not_found' using errcode = 'P0001';
  end if;
  if v_account.status = 'pending_deletion' then
    return v_account.deletion_purge_at;
  end if;
  if v_account.status not in ('active', 'pending_verification') then
    raise exception 'suspended' using errcode = 'P0001';
  end if;

  update public.user_account a
     set status = 'pending_deletion',
         status_before_deletion = v_account.status,
         deletion_requested_at = now(),
         deletion_purge_at = v_purge_at
   where a.user_id = v_user_id;

  delete from public.user_devices d where d.user_id = v_user_id;
  return v_purge_at;
end;
$$;
comment on function public.request_account_deletion() is
  'Deactivates the caller''s account for 30 days and returns the purge date.';
grant execute on function public.request_account_deletion() to authenticated;

-- Restores the caller's account while the grace period is running. The account returns to
-- the status it had before, except that a member whose contact channel was confirmed in the
-- meantime returns as active.
create function public.restore_account()
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user_id constant uuid := kc_private.require_caller();
  v_account public.user_account;
begin
  select a.* into v_account from public.user_account a where a.user_id = v_user_id for update;
  if not found or v_account.status <> 'pending_deletion' then
    raise exception 'not_pending_deletion' using errcode = 'P0001';
  end if;
  if v_account.deletion_purge_at <= now() then
    raise exception 'grace_expired' using errcode = 'P0001';
  end if;

  update public.user_account a
     set status = case
           when exists (select 1 from auth.users au
                         where au.id = v_user_id and kc_private.auth_user_is_verified(au)) then 'active'
           else v_account.status_before_deletion
         end
   where a.user_id = v_user_id;
end;
$$;
comment on function public.restore_account() is 'Restores the caller''s account during the deletion grace period.';
grant execute on function public.restore_account() to authenticated;

-- Accounts whose grace period has ended, oldest first, for the daily purge job. An account
-- stays listed until its auth identity is gone, so a failed purge is retried the next day.
create function kc_private.accounts_due_for_purge(p_limit integer default 100)
returns table (user_id uuid, deletion_purge_at timestamptz)
language sql
stable
set search_path = ''
as $$
  select a.user_id, a.deletion_purge_at
    from public.user_account a
   where a.deletion_purge_at <= now()
   order by a.deletion_purge_at
   limit p_limit;
$$;
comment on function kc_private.accounts_due_for_purge(integer) is
  'Service role only: accounts past their purge date, oldest first.';

-- >>> supabase/schemas/10_identity/100_bootstrap_session.sql
-- Identity · bootstrap_session (docs/db/target-design.md §5 "Session start")
--
-- Everything the app needs to decide what to show after sign-in, in one round trip: the
-- account gate, the caller's private profile and the legal consent prompt. Each later module
-- adds its own top-level key (unread counts, admin roles, survey prompts); existing keys
-- never change shape.
--
-- It runs with the caller's rights: every row it reads is one the caller may already select.

create function public.bootstrap_session()
returns jsonb
language plpgsql
stable
set search_path = ''
as $$
declare
  v_user_id constant uuid := (select auth.uid());
  v_result jsonb;
begin
  select jsonb_build_object(
           'user_id', a.user_id,
           -- Account gate: `status` other than active sends the app to the matching screen.
           'account', jsonb_build_object(
             'status', a.status,
             'status_until', a.status_until,
             'onboarding_state', a.onboarding_state,
             'deletion_requested_at', a.deletion_requested_at,
             'deletion_purge_at', a.deletion_purge_at),
           'private_profile', jsonb_build_object(
             'contact_phone', p.contact_phone,
             'date_of_birth', p.date_of_birth,
             'profile_street', p.profile_street,
             'profile_street_number', p.profile_street_number,
             'notification_preferences', p.notification_preferences,
             'show_active_status', p.show_active_status,
             'closure_explainer_dismissed', p.closure_explainer_dismissed,
             'first_post_nudge_dismissed', p.first_post_nudge_dismissed,
             'basic_info_skipped', p.basic_info_skipped),
           'legal', (
             -- Documents in force whose last material version the caller has not accepted.
             -- `modal` blocks the app; `banner` is the 7-day notice of a standard change,
             -- measured on the database clock (FR-SETTINGS-010 AC3, AC5).
             select jsonb_build_object(
                      'needs_reacknowledgement', count(*) > 0,
                      'blocking', coalesce(bool_or(o.block_mode = 'modal'), false),
                      'documents', coalesce(jsonb_agg(to_jsonb(o) order by o.doc_type), '[]'::jsonb))
               from (
                 select d.doc_type, d.current_version, d.current_effective_date,
                        d.last_material_version, d.last_material_severity,
                        coalesce(c.version, 0) as last_accepted_version,
                        case
                          when d.last_material_severity = 'critical'
                            or now() - d.current_effective_date >= interval '7 days' then 'modal'
                          else 'banner'
                        end as block_mode
                   from public.legal_documents d
                   left join lateral (
                     select max(uc.version) as version
                       from public.user_consents uc
                      where uc.user_id = a.user_id and uc.consent_kind = d.doc_type) c on true
                  where d.current_effective_date <= now()
                    and coalesce(c.version, 0) < d.last_material_version) o))
    into v_result
    from public.user_account a
    join public.user_private p on p.user_id = a.user_id
   where a.user_id = v_user_id;

  if v_result is null then
    raise exception 'unauthenticated' using errcode = '42501';
  end if;
  return v_result;
end;
$$;
comment on function public.bootstrap_session() is
  'Session start in one call: account gate, private profile, legal consent prompt.';
grant execute on function public.bootstrap_session() to authenticated;

-- >>> supabase/schemas/15_social_graph/010_follows.sql
-- Social graph · follows
--
-- One row per "follower follows followed". A private profile is followed through an approved
-- request, so an edge is created only by server code; removing an edge (unfollow, or removing
-- a follower) is a plain delete by either party (FR-FOLLOW-002, FR-FOLLOW-009).

create table public.follows (
  follower_id uuid not null references public.users (id) on delete cascade,
  followed_id uuid not null references public.users (id) on delete cascade,
  created_at  timestamptz not null default now(),
  primary key (follower_id, followed_id),
  constraint follows_not_self_chk check (follower_id <> followed_id)
);
comment on table public.follows is 'Follow edges. Created by server code, deleted by either party.';

-- Followers list of a profile, newest first (keyset on created_at, follower_id).
create index follows_followed_recent_idx on public.follows (followed_id, created_at desc, follower_id);
-- Following list of a profile, newest first; also serves the feed's "people I follow" lookup.
create index follows_follower_recent_idx on public.follows (follower_id, created_at desc, followed_id);

-- Keeps the two profile counters in step with the edge, in the same transaction
-- (FR-FOLLOW-001 AC2). Runs with definer rights because counters are not client-writable.
create function kc_private.follows_sync_counters()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_delta constant integer := case tg_op when 'INSERT' then 1 else -1 end;
  v_edge constant public.follows := case tg_op when 'INSERT' then new else old end;
begin
  update public.user_stats s
     set followers_count = greatest(s.followers_count + v_delta, 0)
   where s.user_id = v_edge.followed_id;
  update public.user_stats s
     set following_count = greatest(s.following_count + v_delta, 0)
   where s.user_id = v_edge.follower_id;
  return null;
end;
$$;

create trigger follows_sync_counters
  after insert or delete on public.follows
  for each row execute function kc_private.follows_sync_counters();

alter table public.follows enable row level security;
alter table public.follows force row level security;

-- Followers and following lists of any member are visible to every signed-in member,
-- whatever the privacy mode (FR-PROFILE-010 AC1). A profile hidden from the viewer drops out
-- when the list is joined to `users`.
create policy follows_select_member on public.follows
  for select to authenticated
  using (true);

-- Unfollow, or remove one of my followers.
create policy follows_delete_party on public.follows
  for delete to authenticated
  using ((select auth.uid()) in (follower_id, followed_id));

grant select, delete on public.follows to authenticated;

-- >>> supabase/schemas/15_social_graph/020_blocks.sql
-- Social graph · blocks
--
-- A block hides two members from each other in both directions. Only the blocker can see or
-- remove the row: the blocked member is never told who blocked them.

create table public.blocks (
  blocker_id uuid not null references public.users (id) on delete cascade,
  blocked_id uuid not null references public.users (id) on delete cascade,
  created_at timestamptz not null default now(),
  primary key (blocker_id, blocked_id),
  constraint blocks_not_self_chk check (blocker_id <> blocked_id)
);
comment on table public.blocks is 'Blocks between members. Visible to the blocker only; effective in both directions.';

-- Reverse lookup: "has this member blocked me?" in the bilateral predicate below.
create index blocks_blocked_idx on public.blocks (blocked_id, blocker_id);

-- True when either member has blocked the other. Definer rights are required because a
-- member cannot read the other side's block row. Used by policies on every table that must
-- hide blocked counterparts.
create function kc_access.is_blocked_between(p_user_a uuid, p_user_b uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1
      from public.blocks b
     where (b.blocker_id = p_user_a and b.blocked_id = p_user_b)
        or (b.blocker_id = p_user_b and b.blocked_id = p_user_a));
$$;
comment on function kc_access.is_blocked_between(uuid, uuid) is
  'Policy predicate: a block exists between the two members, in either direction.';
grant execute on function kc_access.is_blocked_between(uuid, uuid) to authenticated;

-- Blocking ends any follow relation between the two members, in both directions.
create function kc_private.blocks_remove_follows()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  delete from public.follows f
   where (f.follower_id = new.blocker_id and f.followed_id = new.blocked_id)
      or (f.follower_id = new.blocked_id and f.followed_id = new.blocker_id);
  return null;
end;
$$;

create trigger blocks_remove_follows
  after insert on public.blocks
  for each row execute function kc_private.blocks_remove_follows();

alter table public.blocks enable row level security;
alter table public.blocks force row level security;

create policy blocks_select_own on public.blocks
  for select to authenticated
  using (blocker_id = (select auth.uid()));

create policy blocks_insert_own on public.blocks
  for insert to authenticated
  with check (blocker_id = (select auth.uid()));

create policy blocks_delete_own on public.blocks
  for delete to authenticated
  using (blocker_id = (select auth.uid()));

grant select, insert, delete on public.blocks to authenticated;

-- Blocked counterparts disappear from each other. Restrictive, so it narrows whatever the
-- permissive profile policies allow; a member's own row is never affected (no self-block).
create policy users_hide_blocked on public.users
  as restrictive
  for select to authenticated
  using (not kc_access.is_blocked_between((select auth.uid()), id));

-- >>> supabase/schemas/15_social_graph/030_follow_requests.sql
-- Social graph · follow_requests (FR-FOLLOW-003 … FR-FOLLOW-008)
--
-- Following a private profile needs its owner's approval. A request is pending until the
-- target accepts or rejects it or the requester cancels it; resolved rows are kept as
-- history. A rejection is silent and starts a 14-day cooldown for the same pair.

insert into kc_private.fsm_state (machine_id, status) values
  ('follow_request', 'pending'),
  ('follow_request', 'accepted'),
  ('follow_request', 'rejected'),
  ('follow_request', 'cancelled');

-- Who may make each move is part of the edge: the RPC states its role before it writes.
insert into kc_private.fsm_edge (machine_id, from_status, to_status, role) values
  ('follow_request', 'pending', 'accepted', 'target'),
  ('follow_request', 'pending', 'rejected', 'target'),
  ('follow_request', 'pending', 'cancelled', 'requester'),
  -- A block between the two members withdraws the request (FR-MOD-003 AC4).
  ('follow_request', 'pending', 'cancelled', 'system');

create table public.follow_requests (
  id             uuid primary key default gen_random_uuid(),
  requester_id   uuid not null references public.users (id) on delete cascade,
  target_id      uuid not null references public.users (id) on delete cascade,
  status         text not null default 'pending',
  -- Set on rejection: the requester may ask again from this time (FR-FOLLOW-006 AC1).
  cooldown_until timestamptz,
  created_at     timestamptz not null default now(),
  resolved_at    timestamptz,
  constraint follow_requests_not_self_chk check (requester_id <> target_id),
  constraint follow_requests_cooldown_chk check ((cooldown_until is not null) = (status = 'rejected')),
  constraint follow_requests_resolved_chk check ((resolved_at is null) = (status = 'pending'))
);
comment on table public.follow_requests is
  'Requests to follow a private profile. Visible to the two members; moved only by RPCs.';

-- At most one live request per ordered pair.
create unique index follow_requests_one_pending_idx
  on public.follow_requests (requester_id, target_id) where status = 'pending';
-- Follow button state and the cooldown check: the newest request of a pair. Also the
-- foreign key on requester_id.
create index follow_requests_pair_recent_idx
  on public.follow_requests (requester_id, target_id, created_at desc);
-- Follow Requests screen: pending requests of a target, newest first, keyset on
-- (created_at, id) (FR-FOLLOW-007 AC1). Also the foreign key on target_id.
create index follow_requests_target_status_idx
  on public.follow_requests (target_id, status, created_at desc, id desc);

create trigger follow_requests_status_fsm
  before insert or update of status on public.follow_requests
  for each row execute function kc_private.fsm_guard_status('follow_request', 'status');

-- Stamps the resolution time, and the cooldown when the request was rejected.
create function kc_private.follow_requests_stamp_resolution()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  new.resolved_at := now();
  new.cooldown_until := case when new.status = 'rejected' then now() + interval '14 days' end;
  return new;
end;
$$;

create trigger follow_requests_stamp_resolution
  before update of status on public.follow_requests
  for each row
  when (old.status = 'pending' and new.status <> 'pending')
  execute function kc_private.follow_requests_stamp_resolution();

-- An accepted request becomes a follow edge in the same transaction (FR-FOLLOW-005 AC1).
create function kc_private.follow_requests_create_edge()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  insert into public.follows (follower_id, followed_id)
  values (new.requester_id, new.target_id)
  on conflict do nothing;
  return null;
end;
$$;

create trigger follow_requests_create_edge
  after update of status on public.follow_requests
  for each row
  when (old.status = 'pending' and new.status = 'accepted')
  execute function kc_private.follow_requests_create_edge();

-- Blocking withdraws pending requests between the two members, in both directions, so a
-- request can never be approved across a block.
create function kc_private.blocks_cancel_follow_requests()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  -- A block may be inserted by code that acts under a role of its own: put it back after.
  v_outer_role constant text := coalesce(current_setting('kc.fsm_role', true), '');
begin
  perform set_config('kc.fsm_role', 'system', true);
  update public.follow_requests r
     set status = 'cancelled'
   where r.status = 'pending'
     and ((r.requester_id = new.blocker_id and r.target_id = new.blocked_id)
       or (r.requester_id = new.blocked_id and r.target_id = new.blocker_id));
  perform set_config('kc.fsm_role', v_outer_role, true);
  return null;
end;
$$;

create trigger blocks_cancel_follow_requests
  after insert on public.blocks
  for each row execute function kc_private.blocks_cancel_follow_requests();

alter table public.follow_requests enable row level security;
alter table public.follow_requests force row level security;

-- The requester sees their own requests (button state, cooldown end); the target sees the
-- requests addressed to them. Nobody else sees a request.
create policy follow_requests_select_party on public.follow_requests
  for select to authenticated
  using ((select auth.uid()) in (requester_id, target_id));

grant select on public.follow_requests to authenticated;

-- >>> supabase/schemas/15_social_graph/040_follow_rpcs.sql
-- Social graph · follow RPCs and the privacy mode switch
--
-- A follow edge and a follow request are never inserted from a device: these functions
-- decide which of the two a "follow" becomes and who may resolve a request. Errors are
-- raised with SQLSTATE P0001 and a stable snake_case message.

-- The signed-in caller, who must hold an active account: a member waiting for verification,
-- under a sanction or pending deletion cannot act on the social graph.
create function kc_private.require_active_caller()
returns uuid
language plpgsql
stable
set search_path = ''
as $$
declare
  v_user_id constant uuid := kc_private.require_caller();
begin
  if not exists (select 1 from public.users u where u.id = v_user_id and u.is_active) then
    raise exception 'account_not_active' using errcode = 'P0001';
  end if;
  return v_user_id;
end;
$$;
comment on function kc_private.require_active_caller() is
  'Returns auth.uid(); raises unless the caller is signed in with an active account.';

-- Follows a member: an edge at once on a public profile (FR-FOLLOW-001), a pending request
-- on a private one (FR-FOLLOW-003). Returns 'following' or 'requested'; repeating the call
-- returns the same answer without a second row.
create function public.follow_user(p_target uuid)
returns text
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user_id constant uuid := kc_private.require_active_caller();
  v_target public.users;
  v_cooldown_until timestamptz;
begin
  if p_target = v_user_id then
    raise exception 'self_follow_forbidden' using errcode = 'P0001';
  end if;

  -- The share lock makes a concurrent privacy switch of the target wait for this call.
  select u.* into v_target from public.users u where u.id = p_target for share;
  if not found or not v_target.is_active then
    raise exception 'user_unavailable' using errcode = 'P0001';
  end if;
  if kc_access.is_blocked_between(v_user_id, p_target) then
    raise exception 'blocked_relationship' using errcode = 'P0001';
  end if;

  if exists (select 1 from public.follows f
              where f.follower_id = v_user_id and f.followed_id = p_target) then
    return 'following';
  end if;
  if v_target.privacy_mode = 'Public' then
    insert into public.follows (follower_id, followed_id) values (v_user_id, p_target)
    on conflict do nothing;
    return 'following';
  end if;

  if exists (select 1 from public.follow_requests r
              where r.requester_id = v_user_id and r.target_id = p_target and r.status = 'pending') then
    return 'requested';
  end if;

  -- 14 days after a rejection the requester may ask again (FR-FOLLOW-008); the detail
  -- carries the end of the cooldown for the "try again in N days" hint.
  select max(r.cooldown_until) into v_cooldown_until
    from public.follow_requests r
   where r.requester_id = v_user_id and r.target_id = p_target
     and r.status = 'rejected' and r.cooldown_until > now();
  if v_cooldown_until is not null then
    raise exception 'follow_request_cooldown_active' using
      errcode = 'P0001',
      detail = 'cooldown_until='
        || to_char(v_cooldown_until at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"');
  end if;

  insert into public.follow_requests (requester_id, target_id) values (v_user_id, p_target)
  on conflict (requester_id, target_id) where status = 'pending' do nothing;
  return 'requested';
end;
$$;
comment on function public.follow_user(uuid) is
  'Follows a member: an edge on a public profile, a pending request on a private one.';
grant execute on function public.follow_user(uuid) to authenticated;

-- The target accepts or silently rejects a pending request (FR-FOLLOW-005, FR-FOLLOW-006).
create function public.follow_request_decide(p_requester uuid, p_accept boolean)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user_id constant uuid := kc_private.require_active_caller();
  v_moved boolean;
begin
  if p_accept is null then
    raise exception 'invalid_decision' using errcode = 'P0001';
  end if;

  perform set_config('kc.fsm_role', 'target', true);
  update public.follow_requests r
     set status = case when p_accept then 'accepted' else 'rejected' end
   where r.requester_id = p_requester and r.target_id = v_user_id and r.status = 'pending';
  v_moved := found;
  perform set_config('kc.fsm_role', '', true);

  if not v_moved then
    raise exception 'follow_request_not_pending' using errcode = 'P0001';
  end if;
end;
$$;
comment on function public.follow_request_decide(uuid, boolean) is
  'The caller accepts or rejects a pending follow request addressed to them.';
grant execute on function public.follow_request_decide(uuid, boolean) to authenticated;

-- The requester withdraws their own pending request; no cooldown follows (FR-FOLLOW-004).
create function public.follow_request_cancel(p_target uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user_id constant uuid := kc_private.require_caller();
  v_moved boolean;
begin
  perform set_config('kc.fsm_role', 'requester', true);
  update public.follow_requests r
     set status = 'cancelled'
   where r.requester_id = v_user_id and r.target_id = p_target and r.status = 'pending';
  v_moved := found;
  perform set_config('kc.fsm_role', '', true);

  if not v_moved then
    raise exception 'follow_request_not_pending' using errcode = 'P0001';
  end if;
end;
$$;
comment on function public.follow_request_cancel(uuid) is 'The caller withdraws their pending follow request.';
grant execute on function public.follow_request_cancel(uuid) to authenticated;

-- Switches the caller's profile between 'Public' and 'Private' (FR-PROFILE-005/006).
-- The switch is not retroactive for posts or existing followers. Going public accepts every
-- pending request in the same transaction; none of them can be from a blocked member,
-- because a block withdraws the requests between its two members.
create function public.set_privacy_mode(p_mode text)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user_id constant uuid := kc_private.require_active_caller();
begin
  if p_mode is null or p_mode not in ('Public', 'Private') then
    raise exception 'invalid_privacy_mode' using errcode = 'P0001';
  end if;

  update public.users u
     set privacy_mode = p_mode, privacy_changed_at = now()
   where u.id = v_user_id and u.privacy_mode <> p_mode;
  if not found or p_mode = 'Private' then
    return;
  end if;

  perform set_config('kc.fsm_role', 'target', true);
  update public.follow_requests r
     set status = 'accepted'
   where r.target_id = v_user_id and r.status = 'pending';
  perform set_config('kc.fsm_role', '', true);
end;
$$;
comment on function public.set_privacy_mode(text) is
  'Sets the caller''s privacy mode; going public accepts all pending follow requests.';
grant execute on function public.set_privacy_mode(text) to authenticated;

-- >>> supabase/schemas/15_social_graph/050_user_profile_fields.sql
-- Social graph · user_profile_fields (D109, D110, FR-PROFILE-007 AC8/AC9)
--
-- Optional profile fields, one row per member and field, each with its own visibility.
-- The table belongs to the profile, but lives in this module because who may read a field
-- depends on the follow graph.

create table public.user_profile_fields (
  user_id           uuid not null references public.users (id) on delete cascade,
  -- interests: giving worlds and item subcategories the member cares about
  -- help_tags: what the member can help with (giving-world tags)
  -- affiliated_org: a self-declared affiliation; a label only, it grants no role
  field_key         text not null check (field_key in ('interests', 'help_tags', 'affiliated_org')),
  -- Who may read the field. Left empty on insert, it follows the owner's privacy mode at
  -- that moment: everyone on a public profile, followers on a private one.
  visibility        text not null check (visibility in ('everyone', 'followers', 'only_me')),
  -- Value of the two tag fields: 1 to 50 slugs.
  tags              text[] check (
                      cardinality(tags) between 1 and 50
                      and array_to_string(tags, ' ', '') ~ '^[a-z0-9_.:-]{1,64}( [a-z0-9_.:-]{1,64})*$'),
  -- Value of affiliated_org. The organizations module adds the foreign key and restricts
  -- it to verified organizations.
  affiliated_org_id uuid,
  updated_at        timestamptz not null default now(),
  primary key (user_id, field_key),
  constraint user_profile_fields_value_chk check (
    case when field_key = 'affiliated_org'
      then affiliated_org_id is not null and tags is null
      else tags is not null and affiliated_org_id is null
    end)
);
comment on table public.user_profile_fields is
  'Optional profile fields with per-field visibility. A missing row means the field is not filled in.';

-- Members affiliated with an organization (organization page; future foreign key).
create index user_profile_fields_affiliated_org_idx
  on public.user_profile_fields (affiliated_org_id) where affiliated_org_id is not null;

-- Applies the default visibility. Runs with the caller's rights: the owner can always read
-- their own profile row.
create function kc_private.user_profile_fields_default_visibility()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  select case u.privacy_mode when 'Private' then 'followers' else 'everyone' end
    into new.visibility
    from public.users u where u.id = new.user_id;
  return new;
end;
$$;

create trigger user_profile_fields_default_visibility
  before insert on public.user_profile_fields
  for each row
  when (new.visibility is null)
  execute function kc_private.user_profile_fields_default_visibility();

create trigger user_profile_fields_set_updated_at
  before update on public.user_profile_fields
  for each row execute function kc_private.set_updated_at();

alter table public.user_profile_fields enable row level security;
alter table public.user_profile_fields force row level security;

-- The owner reads every field. Anyone else reads a field only when the owner's profile is
-- visible to them (so never across a block, and never for an inactive account) and the
-- field is open to everyone, or open to followers and the reader follows the owner.
create policy user_profile_fields_select_visible on public.user_profile_fields
  for select to authenticated
  using (
    user_id = (select auth.uid())
    or (visibility <> 'only_me'
        and exists (
          select 1
            from public.users u
           where u.id = user_profile_fields.user_id
             and (user_profile_fields.visibility = 'everyone'
                  or exists (select 1 from public.follows f
                              where f.follower_id = (select auth.uid())
                                and f.followed_id = u.id)))));

create policy user_profile_fields_insert_self on public.user_profile_fields
  for insert to authenticated
  with check (user_id = (select auth.uid()));

create policy user_profile_fields_update_self on public.user_profile_fields
  for update to authenticated
  using (user_id = (select auth.uid()))
  with check (user_id = (select auth.uid()));

-- Clearing a field is deleting its row.
create policy user_profile_fields_delete_self on public.user_profile_fields
  for delete to authenticated
  using (user_id = (select auth.uid()));

grant select, insert, delete on public.user_profile_fields to authenticated;
grant update (visibility, tags, affiliated_org_id) on public.user_profile_fields to authenticated;

-- >>> supabase/schemas/20_posts/010_catalog.sql
-- Posts · catalog (giving worlds, post kinds, item subcategories)
--
-- Configuration that decides what a post may be. Rows are loaded by the seed scripts and
-- changed only by migrations or server code: a device can read the catalog, never write it.
-- One list of giving worlds, with no second "domain" layer (D100).

-- A giving world (D100) and its per-world behaviour.
create table public.worlds (
  slug                    text primary key check (slug ~ '^[a-z][a-z0-9_]{1,30}$'),
  label_he                text not null,
  label_en                text not null,
  -- How careful the product is with this world's content (review, exposure).
  sensitivity             text not null default 'standard'
                            check (sensitivity in ('standard', 'elevated', 'restricted')),
  -- Publishing in this world requires a verified identity (for example housing, D30).
  requires_verification   boolean not null default false,
  -- Default audience of the poster's identity: 1 operators only · 2 followers · 3 everyone.
  default_anonymity_level smallint not null default 3 check (default_anonymity_level between 1 and 3),
  -- Default lifetime of a post; null = posts of this world do not expire (D21).
  default_ttl_hours       integer check (default_ttl_hours > 0),
  -- Whether distance matters: nearby, same region, or not at all (online).
  geo_mode                text not null default 'local' check (geo_mode in ('local', 'regional', 'remote')),
  default_radius_km       numeric(8, 2) not null default 25 check (default_radius_km > 0),
  -- Share of distance in ranking and matching for this world, 0 to 1.
  geo_weight              numeric(4, 3) not null default 1 check (geo_weight between 0 and 1),
  -- Posts of this world also appear in the main feed, not only on the world's own screen.
  shows_in_main_feed      boolean not null default false,
  -- An inactive world is kept for its existing posts but accepts no new ones.
  is_active               boolean not null default true,
  sort_order              integer not null default 0,
  created_at              timestamptz not null default now()
);
comment on table public.worlds is 'Giving worlds (D100) and their per-world configuration.';

-- What can be posted in a world: "ride offer", "lesson request", "item". Each kind owns the
-- JSON Schema of the type-specific fields stored in posts.details.
create table public.post_kinds (
  id                uuid primary key default gen_random_uuid(),
  world_slug        text not null references public.worlds (slug) on update cascade on delete cascade,
  slug              text not null check (slug ~ '^[a-z][a-z0-9_]{1,40}$'),
  label_he          text not null,
  label_en          text not null,
  -- Which side may use this kind; posts.direction must agree.
  direction         text not null check (direction in ('offer', 'request', 'either')),
  -- JSON Schema for posts.details of this kind.
  detail_schema     jsonb not null default '{"type":"object"}'::jsonb
                      check (jsonb_typeof(detail_schema) = 'object'),
  -- Overrides the world's default lifetime; null = follow the world.
  default_ttl_hours integer check (default_ttl_hours > 0),
  is_active         boolean not null default true,
  sort_order        integer not null default 0,
  created_at        timestamptz not null default now(),
  constraint post_kinds_world_slug_key unique (world_slug, slug),
  -- Target of the composite foreign key that keeps a post's kind inside the post's world.
  constraint post_kinds_id_world_key unique (id, world_slug)
);
comment on table public.post_kinds is 'Kinds of post per giving world; detail_schema describes posts.details.';

-- Kind picker of a world's create form (also covers the world_slug foreign key).
create index post_kinds_world_order_idx on public.post_kinds (world_slug, sort_order);

-- Sub-categories of a giving world, as a tree (item subcategory, food type, knowledge shelf).
-- Replaces the fixed item list that used to be a check constraint on posts.
create table public.item_subcategories (
  id         uuid primary key default gen_random_uuid(),
  world_slug text not null references public.worlds (slug) on update cascade on delete cascade,
  parent_id  uuid,
  slug       text not null check (slug ~ '^[a-z][a-z0-9_]{1,40}$'),
  label_he   text not null,
  label_en   text not null,
  is_active  boolean not null default true,
  sort_order integer not null default 0,
  created_at timestamptz not null default now(),
  constraint item_subcategories_world_slug_key unique (world_slug, slug),
  constraint item_subcategories_id_world_key unique (id, world_slug),
  constraint item_subcategories_not_own_parent_chk check (parent_id <> id),
  -- A child always belongs to its parent's world.
  constraint item_subcategories_parent_fk foreign key (parent_id, world_slug)
    references public.item_subcategories (id, world_slug) on update cascade on delete cascade
);
comment on table public.item_subcategories is 'Per-world sub-category tree; a post points at one node of its own world.';

-- Children of a node in display order: the subcategory picker and browse filters.
create index item_subcategories_tree_idx on public.item_subcategories (world_slug, parent_id, sort_order);
-- Covers the parent foreign key (cascade on removing a node).
create index item_subcategories_parent_idx on public.item_subcategories (parent_id) where parent_id is not null;

alter table public.worlds enable row level security;
alter table public.worlds force row level security;
alter table public.post_kinds enable row level security;
alter table public.post_kinds force row level security;
alter table public.item_subcategories enable row level security;
alter table public.item_subcategories force row level security;

-- Read-only configuration for signed-in members. No insert, update or delete policy and no
-- write grant exist, so the catalog cannot be changed from a device.
create policy worlds_select_member on public.worlds
  for select to authenticated
  using (true);
create policy post_kinds_select_member on public.post_kinds
  for select to authenticated
  using (true);
create policy item_subcategories_select_member on public.item_subcategories
  for select to authenticated
  using (true);

grant select on public.worlds to authenticated;
grant select on public.post_kinds to authenticated;
grant select on public.item_subcategories to authenticated;

-- >>> supabase/schemas/20_posts/020_posts.sql
-- Posts · posts (the one content table of every giving world)
--
-- Everything published in the product is one post (D2, D19): a primary giving world, a kind, a
-- direction, a lifecycle status and an audience. Fields that only some worlds have live in
-- `details` (validated against post_kinds.detail_schema) or in a 1:1 detail table added by
-- that world's module. The exact address is never stored here (post_private_locations).

create table public.posts (
  id                     uuid primary key default gen_random_uuid(),
  owner_id               uuid not null references public.users (id) on delete cascade,
  -- Organization the post is published for. The foreign key is added by the organizations
  -- module, which creates the referenced table.
  beneficiary_org_id     uuid,
  world_slug             text not null references public.worlds (slug) on update cascade,
  kind_id                uuid not null,
  -- Which 1:1 detail table, if any, extends the post.
  post_type              text not null default 'standard'
                           check (post_type in ('standard', 'ride', 'event', 'housing_stay', 'job', 'challenge')),
  direction              text not null check (direction in ('offer', 'request')),
  -- Lifecycle, machine `post` (030_post_status_machine.sql). Never written by a device.
  status                 text not null default 'open',
  -- Status held when an admin removed the post; a restore returns to it (D129).
  status_before_removal  text check (status_before_removal in
                           ('open', 'paused', 'closed_delivered', 'deleted_no_recipient', 'expired')),
  -- Audience chosen by the owner; may change freely after publishing (FR-POST-009).
  visibility             text not null default 'Public'
                           check (visibility in ('Public', 'FollowersOnly', 'OnlyMe')),
  title                  text not null check (char_length(title) between 1 and 80),
  description            text check (char_length(description) <= 500),
  item_subcategory_id    uuid,
  -- Type-specific fields. Only the shape is checked here; validation against the kind's
  -- JSON Schema is added with the module that enables the schema validator.
  details                jsonb not null default '{}'::jsonb check (jsonb_typeof(details) = 'object'),
  city_id                text not null references public.cities (city_id),
  -- How precisely the location is shown to others (FR-POST-003 AC3).
  location_display_level text not null default 'CityAndStreet'
                           check (location_display_level in ('CityOnly', 'CityAndStreet', 'FullAddress')),
  -- The only location other members, the map and matching ever read. Derived by trigger
  -- (050_post_private_locations.sql); never the exact address.
  geo_approx             extensions.geography(Point, 4326),
  -- When the offer or need applies (event time, availability window).
  time_window            tstzrange check (not isempty(time_window)),
  -- 1 low · 2 medium · 3 high.
  urgency_level          smallint check (urgency_level between 1 and 3),
  -- When the post closes by itself; null = never (D21). Set by server code per post kind.
  expires_at             timestamptz,
  -- 'imported' marks a post brought in from an external channel until it is claimed.
  source                 text not null default 'native' check (source in ('native', 'imported')),
  -- Detected BCP 47 language of title and description; written by the translation pipeline.
  source_language        text check (char_length(source_language) between 2 and 35),
  -- Search document; `simple` keeps Hebrew tokens unstemmed.
  search_vector          tsvector generated always as (
                           to_tsvector('simple', title || ' ' || coalesce(description, ''))) stored,
  -- First time the post became open; the feed sorts on it. Null while a draft.
  published_at           timestamptz,
  created_at             timestamptz not null default now(),
  updated_at             timestamptz not null default now(),
  -- The kind and the subcategory must belong to the post's own world.
  constraint posts_kind_fk foreign key (kind_id, world_slug)
    references public.post_kinds (id, world_slug) on update cascade,
  constraint posts_item_subcategory_fk foreign key (item_subcategory_id, world_slug)
    references public.item_subcategories (id, world_slug) on update cascade,
  -- The saved status exists exactly while the post is removed.
  constraint posts_removal_memory_chk
    check ((status = 'removed_admin') = (status_before_removal is not null)),
  -- A draft has never been published; every other status has.
  constraint posts_published_chk check ((status = 'draft') = (published_at is null))
);
comment on table public.posts is 'Every post of every giving world. Status moves only through server code.';

-- Main feed: open public posts, newest first (keyset on published_at, id).
create index posts_feed_recent_idx on public.posts (published_at desc, id desc)
  where status = 'open' and visibility = 'Public';
-- A profile's posts and "my posts" in any status, newest first; covers the owner foreign key.
create index posts_owner_recent_idx on public.posts (owner_id, created_at desc, id desc);
-- Browse a world by status, newest first; covers the world foreign key.
create index posts_world_status_recent_idx on public.posts (world_slug, status, published_at desc, id desc);
-- Feed and browse filtered by city; covers the city foreign key.
create index posts_city_recent_idx on public.posts (city_id, published_at desc, id desc) where status = 'open';
-- Expiry sweep: live posts whose time has come.
create index posts_expiry_due_idx on public.posts (expires_at)
  where expires_at is not null and status in ('open', 'paused');
-- Whole-word search over open posts.
create index posts_search_gin_idx on public.posts using gin (search_vector) where status = 'open';
-- Substring search over open posts (Hebrew has no useful stemming). A query must use the
-- same expression: (title || ' ' || coalesce(description, '')) ilike '%…%'.
create index posts_text_trgm_idx on public.posts
  using gin ((title || ' ' || coalesce(description, '')) extensions.gin_trgm_ops) where status = 'open';
-- Radius search, map pins and matching over open posts.
create index posts_geo_approx_gist_idx on public.posts using gist (geo_approx) where status = 'open';
-- Foreign keys to the catalog (a kind or subcategory being retired or renamed).
create index posts_kind_idx on public.posts (kind_id);
create index posts_item_subcategory_idx on public.posts (item_subcategory_id)
  where item_subcategory_id is not null;

create trigger posts_set_updated_at
  before update on public.posts
  for each row execute function kc_private.set_updated_at();

-- >>> supabase/schemas/20_posts/030_post_status_machine.sql
-- Posts · lifecycle (machine `post`: spec state machine S1 plus `draft`)
--
--   draft ─► open ◄─► paused
--             ├─► closed_delivered ─► open            (reopen, owner only)
--             ├─► deleted_no_recipient ─► open        (reopen, owner only)
--             └─► expired                             (never reopened: republish is a new post, D127)
--   live ─► hidden_pending_review ─► open | removed_admin
--   any published ─► removed_admin ─► the status held before the removal (D129)
--
-- Each edge names who may take it. The RPC performing a move states its role in the
-- transaction-local setting `kc.fsm_role`; a write without a role (or with the wrong one)
-- is refused, and a device has no UPDATE privilege on the column at all.
--   owner   the member who owns the post (D104)
--   admin   a moderator acting on the post
--   system  sweeps and automatic moderation (expiry D21 / D128, review hide D33, handoff completion)

insert into kc_private.fsm_state (machine_id, status) values
  ('post', 'draft'),
  ('post', 'open'),
  ('post', 'paused'),
  ('post', 'closed_delivered'),
  ('post', 'deleted_no_recipient'),
  ('post', 'expired'),
  ('post', 'hidden_pending_review'),
  ('post', 'removed_admin');

insert into kc_private.fsm_edge (machine_id, from_status, to_status, role) values
  -- Owner management (D104).
  ('post', 'draft', 'open', 'owner'),
  ('post', 'open', 'paused', 'owner'),
  ('post', 'paused', 'open', 'owner'),
  ('post', 'open', 'closed_delivered', 'owner'),
  ('post', 'open', 'deleted_no_recipient', 'owner'),
  ('post', 'paused', 'deleted_no_recipient', 'owner'),
  ('post', 'expired', 'deleted_no_recipient', 'owner'),
  ('post', 'hidden_pending_review', 'deleted_no_recipient', 'owner'),
  ('post', 'closed_delivered', 'open', 'owner'),
  ('post', 'deleted_no_recipient', 'open', 'owner'),
  -- A handoff completed by the other side closes the post; a recipient who removes their
  -- mark turns a delivered post into one closed without a recipient (FR-CLOSURE-007).
  ('post', 'open', 'closed_delivered', 'system'),
  ('post', 'hidden_pending_review', 'closed_delivered', 'system'),
  ('post', 'closed_delivered', 'deleted_no_recipient', 'system'),
  -- Expiry sweeps.
  ('post', 'open', 'expired', 'system'),
  ('post', 'paused', 'expired', 'system'),
  -- Automatic hide while reports are reviewed, and its automatic lift.
  ('post', 'open', 'hidden_pending_review', 'system'),
  ('post', 'paused', 'hidden_pending_review', 'system'),
  ('post', 'closed_delivered', 'hidden_pending_review', 'system'),
  ('post', 'expired', 'hidden_pending_review', 'system'),
  ('post', 'hidden_pending_review', 'open', 'system'),
  -- Moderation: a review outcome, a removal from any published status, and its restore.
  ('post', 'hidden_pending_review', 'open', 'admin'),
  ('post', 'open', 'removed_admin', 'admin'),
  ('post', 'paused', 'removed_admin', 'admin'),
  ('post', 'closed_delivered', 'removed_admin', 'admin'),
  ('post', 'deleted_no_recipient', 'removed_admin', 'admin'),
  ('post', 'expired', 'removed_admin', 'admin'),
  ('post', 'hidden_pending_review', 'removed_admin', 'admin'),
  ('post', 'removed_admin', 'open', 'admin'),
  ('post', 'removed_admin', 'paused', 'admin'),
  ('post', 'removed_admin', 'closed_delivered', 'admin'),
  ('post', 'removed_admin', 'deleted_no_recipient', 'admin'),
  ('post', 'removed_admin', 'expired', 'admin');

create trigger posts_status_fsm
  before insert or update of status on public.posts
  for each row execute function kc_private.fsm_guard_status('post', 'status');

-- Rules of a status write that the graph alone cannot express. Fires after posts_status_fsm
-- (triggers run in name order), so the move itself is already known to be legal.
--   insert   the kind must be active and admit the post's direction
--   publish  stamps the first time the post leaves draft
--   → open   an owner may hold at most 20 open posts (FR-POST-011); a paused post is not
--            resumed after its own expiry (D104)
--   removal  remembers the status the post is removed from, and a restore may only return
--            to it (D129); a post hidden for review counts as open
-- Definer rights: it reads the catalog and locks the owner's counter row, which a member
-- may not write.
create function kc_private.posts_apply_status_rules()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_from constant text := case tg_op when 'UPDATE' then old.status end;
  v_open_limit constant integer := 20;
begin
  if tg_op = 'INSERT' and not exists (
       select 1 from public.post_kinds k
        where k.id = new.kind_id and k.is_active and k.direction in (new.direction, 'either')) then
    raise exception 'post_kind_not_allowed' using errcode = 'P0001',
      detail = 'the post kind is inactive or does not admit this direction';
  end if;

  if v_from is not distinct from new.status then
    return new;
  end if;

  -- Leaving draft (or being created past it, as an imported post is) is the publish moment.
  if new.status <> 'draft' then
    new.published_at := coalesce(new.published_at, now());
  end if;

  if new.status = 'open' then
    if v_from = 'paused' and new.expires_at <= now() then
      raise exception 'post_expired' using errcode = 'P0001', detail = 'a post is not resumed after its expiry';
    end if;
    -- Moderation and sweeps return a post to open regardless of the owner's quota.
    if coalesce(current_setting('kc.fsm_role', true), '') not in ('admin', 'system') then
      -- The counter row is the per-owner lock: two concurrent publishes cannot both pass.
      perform 1 from public.user_stats s where s.user_id = new.owner_id for update;
      if (select count(*) from public.posts p where p.owner_id = new.owner_id and p.status = 'open')
         >= v_open_limit then
        raise exception 'post_limit_exceeded' using errcode = 'P0001',
          detail = format('at most %s open posts per member', v_open_limit);
      end if;
    end if;
  end if;

  if new.status = 'removed_admin' then
    new.status_before_removal := case v_from when 'hidden_pending_review' then 'open' else v_from end;
  elsif v_from = 'removed_admin' then
    if new.status is distinct from old.status_before_removal then
      raise exception 'illegal_transition' using errcode = 'P0001',
        detail = format('post: a removed post is restored to %s', old.status_before_removal);
    end if;
    new.status_before_removal := null;
  end if;

  return new;
end;
$$;
comment on function kc_private.posts_apply_status_rules() is
  'BEFORE INSERT OR UPDATE OF status on posts: kind check, publish time, open-post quota, removal memory.';

create trigger posts_status_rules
  before insert or update of status on public.posts
  for each row execute function kc_private.posts_apply_status_rules();

-- >>> supabase/schemas/20_posts/040_post_access.sql
-- Posts · who may read and write a post
--
-- Visibility is decided by indexed columns and one lookup on `follows`; no function is
-- evaluated over the row. Nothing is granted to signed-out callers.

alter table public.posts enable row level security;
alter table public.posts force row level security;

-- The owner sees their own posts in every status, whatever their account state.
create policy posts_select_owner on public.posts
  for select to authenticated
  using (owner_id = (select auth.uid()));

-- Another member sees a post when all three hold:
--   1. status — only `open` and `closed_delivered`. A delivered post stays on the giver's
--      profile as their record of giving (FR-PROFILE-001 closed tab, FR-POST-021). Drafts,
--      paused posts (D104), posts closed without a recipient, expired posts and posts hidden
--      or removed by moderation are the owner's alone.
--   2. audience — `Public`, or `FollowersOnly` when the viewer follows the owner. `OnlyMe`
--      never matches.
--   3. owner — the owner's profile is visible to the viewer. The subquery runs under the
--      viewer's own access to `users`, so it inherits that table's rules: the owner's
--      account is active and no block exists between the two, in either direction.
-- Extension points (later modules add policies; this one does not change): moderators read
-- every post; the counterparty of a handoff reads the post whatever its audience; a
-- member's own report hides the post from them (restrictive policy).
create policy posts_select_visible on public.posts
  for select to authenticated
  using (
    status in ('open', 'closed_delivered')
    and (visibility = 'Public'
         or (visibility = 'FollowersOnly'
             and exists (select 1 from public.follows f
                          where f.follower_id = (select auth.uid()) and f.followed_id = posts.owner_id)))
    and exists (select 1 from public.users u where u.id = posts.owner_id));

-- A member creates their own post, as a draft or already open, written in the product
-- (never 'imported'). A member whose account is not active cannot post (spec 7.1, S2).
create policy posts_insert_owner on public.posts
  for insert to authenticated
  with check (
    owner_id = (select auth.uid())
    and status in ('draft', 'open')
    and exists (select 1 from public.users u where u.id = (select auth.uid()) and u.is_active));

-- The owner edits content while the post is a draft, open or paused; once closed, expired
-- or under moderation the content is locked (D104). Which columns is decided by the grant.
create policy posts_update_owner on public.posts
  for update to authenticated
  using (
    owner_id = (select auth.uid())
    and status in ('draft', 'open', 'paused')
    and exists (select 1 from public.users u where u.id = (select auth.uid()) and u.is_active))
  with check (owner_id = (select auth.uid()));

-- Only a draft is ever deleted from a device: it was never published, so nobody else holds
-- a record of it. Removing a published post is a status move (`deleted_no_recipient`) made
-- by an RPC, and the row is purged by a server job after its grace period (design §4.1).
create policy posts_delete_owner_draft on public.posts
  for delete to authenticated
  using (owner_id = (select auth.uid()) and status = 'draft');

grant select, delete on public.posts to authenticated;

-- Insert: everything the create form sets. Status is limited to draft / open by the policy.
-- Not insertable: beneficiary_org_id, expires_at, source, source_language, geo_approx,
-- status_before_removal, published_at, timestamps — all server-written.
grant insert (
  id, owner_id, world_slug, kind_id, post_type, direction, status, visibility, title, description,
  item_subcategory_id, details, city_id, location_display_level, time_window, urgency_level
) on public.posts to authenticated;

-- Update: content only. The owner, world, kind, post type and direction are fixed at
-- creation (FR-POST-008 AC2); status moves through RPCs; derived columns are never writable.
grant update (
  visibility, title, description, item_subcategory_id, details, city_id, location_display_level,
  time_window, urgency_level
) on public.posts to authenticated;

-- >>> supabase/schemas/20_posts/050_post_private_locations.sql
-- Posts · exact address and the approximate location shown to others (design §3.9)
--
-- The exact point of a post lives only in `post_private_locations`, readable by its owner.
-- Everyone else — feed, map, distance search, matching — reads `posts.geo_approx`, which is
-- derived here and can never be written directly. Releasing the exact address to the
-- counterparty of a confirmed handoff is an audited RPC of the handoffs module.

create table public.post_private_locations (
  post_id       uuid primary key references public.posts (id) on delete cascade,
  -- Geocoded position of the address; null until the address has been resolved.
  exact_point   extensions.geography(Point, 4326),
  street        text check (char_length(btrim(street)) between 1 and 80),
  -- Digits with an optional entrance letter, Latin or Hebrew (U+05D0–U+05EA).
  street_number text check (street_number ~ '^[0-9]+[A-Za-z\u05D0-\u05EA]?$'),
  -- Free text for the person arriving: floor, entrance code, where to leave things.
  access_notes  text check (char_length(access_notes) <= 300),
  updated_at    timestamptz not null default now(),
  -- A house number only makes sense with a street.
  constraint post_private_locations_number_needs_street_chk
    check (street_number is null or street is not null)
);
comment on table public.post_private_locations is 'Exact address of a post. Readable and writable by the post owner only.';

create trigger post_private_locations_set_updated_at
  before update on public.post_private_locations
  for each row execute function kc_private.set_updated_at();

-- Approximate location of a post for the given display level.
--   CityOnly        the city centre
--   CityAndStreet   the city centre for now; the geo-reference module, which brings the
--                   street list, replaces this branch with the street centroid
--   FullAddress     the exact point snapped to a grid of 0.003° (about 300 m), then moved by
--                   an offset of up to half a cell that is fixed per post. The offset is
--                   taken from a hash of the post id, so it never changes between
--                   derivations, and any exact point inside the same cell yields the same
--                   result. Without an exact point the city centre is used.
create function kc_private.post_geo_approx(
  p_post_id uuid,
  p_city_id text,
  p_display_level text,
  p_exact_point extensions.geography
)
returns extensions.geography
language sql
stable
set search_path = ''
as $$
  with cell as (select 0.003::double precision as size),
       hash as (select md5(p_post_id::text) as hex)
  select case
    when p_display_level = 'FullAddress' and p_exact_point is not null then
      extensions.st_translate(
        extensions.st_snaptogrid(p_exact_point::extensions.geometry, cell.size),
        -- Two independent values in [-0.5, 0.5) of a cell, from separate parts of the hash.
        (('x' || substr(hash.hex, 1, 8))::bit(32)::bigint / 4294967296.0 - 0.5) * cell.size,
        (('x' || substr(hash.hex, 9, 8))::bit(32)::bigint / 4294967296.0 - 0.5) * cell.size
      )::extensions.geography
    else (select c.location from public.cities c where c.city_id = p_city_id)
  end
  from cell, hash;
$$;
comment on function kc_private.post_geo_approx(uuid, text, text, extensions.geography) is
  'Approximate public location of a post: city centre, or the exact point coarsened to about 300 m.';

-- Keeps posts.geo_approx derived on every write that could change it. On insert the private
-- location does not exist yet, so the post starts at the city centre and is refined by the
-- trigger on post_private_locations below. Definer rights: the derivation is internal.
create function kc_private.posts_set_geo_approx()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  new.geo_approx := kc_private.post_geo_approx(
    new.id, new.city_id, new.location_display_level,
    (select l.exact_point from public.post_private_locations l where l.post_id = new.id));
  return new;
end;
$$;

-- `geo_approx` is in the column list so that a server-side write to it is overwritten too.
create trigger posts_set_geo_approx
  before insert or update of city_id, location_display_level, geo_approx on public.posts
  for each row execute function kc_private.posts_set_geo_approx();

-- Re-derives the post's approximate location when its exact point is set, moved or removed.
-- Definer rights: the owner has no UPDATE privilege on posts.geo_approx.
create function kc_private.post_private_locations_refresh_geo()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_post_id constant uuid := case tg_op when 'DELETE' then old.post_id else new.post_id end;
begin
  -- Writing the column fires posts_set_geo_approx, which computes the value.
  update public.posts p set geo_approx = null where p.id = v_post_id;
  return null;
end;
$$;

create trigger post_private_locations_refresh_geo
  after insert or delete or update of exact_point on public.post_private_locations
  for each row execute function kc_private.post_private_locations_refresh_geo();

alter table public.post_private_locations enable row level security;
alter table public.post_private_locations force row level security;

-- Every policy asks the same question: is the caller the owner of the post? The subquery
-- runs under the caller's access to `posts` and is a primary-key lookup.
create policy post_private_locations_select_owner on public.post_private_locations
  for select to authenticated
  using (exists (select 1 from public.posts p
                  where p.id = post_private_locations.post_id and p.owner_id = (select auth.uid())));

create policy post_private_locations_insert_owner on public.post_private_locations
  for insert to authenticated
  with check (exists (select 1 from public.posts p
                       where p.id = post_private_locations.post_id and p.owner_id = (select auth.uid())));

-- The address is editable exactly while the post's content is (draft, open, paused; D104).
create policy post_private_locations_update_owner on public.post_private_locations
  for update to authenticated
  using (exists (select 1 from public.posts p
                  where p.id = post_private_locations.post_id and p.owner_id = (select auth.uid())
                    and p.status in ('draft', 'open', 'paused')))
  with check (exists (select 1 from public.posts p
                       where p.id = post_private_locations.post_id and p.owner_id = (select auth.uid())));

grant select on public.post_private_locations to authenticated;
grant insert (post_id, exact_point, street, street_number, access_notes)
  on public.post_private_locations to authenticated;
-- The row cannot be moved to another post.
grant update (exact_point, street, street_number, access_notes)
  on public.post_private_locations to authenticated;

-- >>> supabase/schemas/20_posts/060_post_counters.sql
-- Posts · profile counters
--
-- user_stats holds, per member, the number of open posts in each audience and the number of
-- posts ever published. A viewer is shown the sum of the audiences they may see
-- (FR-PROFILE-013), so the three open counters are kept apart.

-- Applies the effect of one post write to its owner's counters, in the same transaction.
-- A post counts as open only in status `open`; it counts as created the moment it is first
-- published, and stays counted when it is later closed or deleted. Definer rights: counters
-- are not writable by members. When the owner's account is being removed the counter row
-- is already gone and the update matches nothing.
create function kc_private.posts_sync_user_stats()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  -- Audience the post was counted under before / is counted under after; null = not open.
  v_old constant text := case when tg_op <> 'INSERT' and old.status = 'open' then old.visibility end;
  v_new constant text := case when tg_op <> 'DELETE' and new.status = 'open' then new.visibility end;
  v_published constant integer := case
    when tg_op = 'INSERT' and new.published_at is not null then 1
    when tg_op = 'UPDATE' and old.published_at is null and new.published_at is not null then 1
    else 0 end;
  v_owner_id constant uuid := case tg_op when 'DELETE' then old.owner_id else new.owner_id end;
begin
  if v_old is not distinct from v_new and v_published = 0 then
    return null;
  end if;

  update public.user_stats s
     set open_posts_public = greatest(s.open_posts_public
           + (v_new is not distinct from 'Public')::integer - (v_old is not distinct from 'Public')::integer, 0),
         open_posts_followers_only = greatest(s.open_posts_followers_only
           + (v_new is not distinct from 'FollowersOnly')::integer
           - (v_old is not distinct from 'FollowersOnly')::integer, 0),
         open_posts_only_me = greatest(s.open_posts_only_me
           + (v_new is not distinct from 'OnlyMe')::integer - (v_old is not distinct from 'OnlyMe')::integer, 0),
         posts_created_total = s.posts_created_total + v_published
   where s.user_id = v_owner_id;
  return null;
end;
$$;
comment on function kc_private.posts_sync_user_stats() is
  'AFTER trigger on posts: keeps the owner''s open-post and created-post counters in step.';

create trigger posts_sync_user_stats
  after insert or delete or update of status, visibility on public.posts
  for each row execute function kc_private.posts_sync_user_stats();
